///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        edt_BASE_DD.setValue($c.ut.cGetToday("yyyymmdd"));
        panel_YYYY.hide();
        edt_BASE_YYYY.setValue($c.ut.cGetToday("yyyymmdd").substring(0, 4));
        MaxTab_01.setSelectedTabIndex(1);
        if (js_market === "1" || js_market === "2") {
            panel_mkt_gubun.hide();
            rdo_MARKET_TP_CD.setValue(js_market);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20001.onpageload" });
    }
};

