///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        let tIndex = MaxTab_01.getSelectedTabIndex();
        if (tIndex === 1) {
            await scwin.listSync1();
        } else if (tIndex === 2) {
            await scwin.listSync2();
        } else if (tIndex === 3) {
            await scwin.listSync3();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20001.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    try {
        if (MaxTab_01.getSelectedTabIndex() === 2) {
            panel_page.show("");
            let Rows;
            if (dts_List_2.getRowCount() > 0) {
                Rows = dts_List_2.getCellData(dts_List_2.getRowCount(), "NO");
            } else {
                Rows = '';
            }
            $c.stf.fillGridHeaderTotalCnt(Rows, panel_page);
        } else {
            panel_page.hide();
        }
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            panel_DD.show("");
            panel_YYYY.hide();
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            panel_DD.show("");
            panel_YYYY.hide();
        } else if (MaxTab_01.getSelectedTabIndex() === 3) {
            panel_DD.hide();
            panel_YYYY.show("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20001.MaxTab_01_OnSelChanged" });
    }
};

