/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF20001.xml", SCREN_PROCS_TP_CD_07); // 엑셀
        let tIndex = MaxTab_01.getSelectedTabIndex();
        if (tIndex === 1) {
            $c.data.downloadGridViewExcel(grd_List_1, {fileName: "상장법인 현황", type: "8"});
        } else if (tIndex === 2) {
            $c.data.downloadGridViewExcel(grd_List_2, {fileName: "관리종목지정 현황", type: "8"});
        } else if (tIndex === 3) {
            $c.data.downloadGridViewExcel(grd_List_3, {fileName: "신규상장 법인현황", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20001.btn_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync1
 * @description list Sync1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync1 = async function() {
    if (!await scwin.checkSearch()) return;

    // if (! fn_TrHoldyYn(dts_CHECK, getObjectValue(edt_BASE_DD)) ) {    return;    }

    url += "?SCREN_ID=" + "ULDSTF20001.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LISTSRH_MAINSTAT_CORPLISTING_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.mainstat.corplisting.condition" + "&{P}param01=" + edt_BASE_DD.getValue() + "&{P}param02=" + edt_BASE_DD.getValue() + "&{P}param03=" + rdo_MARKET_TP_CD.getValue() + "&{P}param04=" + edt_BASE_DD.getValue() + "&{P}param05=" + edt_BASE_DD.getValue() + "&{P}param06=" + rdo_MARKET_TP_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_List_1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // grd_List_1.ColumnProp('DEP_NM', 'BgColor') = "Yellow";

};

/**
 * @method
 * @name listSync2
 * @description list Sync2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync2 = async function() {
    if (!await scwin.checkSearch()) return;
    url += "?SCREN_ID=" + "ULDSTF20001.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LISTSRH_MAINSTAT_ADMISU_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    if (rdo_MARKET_TP_CD.getValue() === '1') {
        url += "&queryId=lds.stf.lstsrch.select.mainstat.admisu.kse.condition" + "&{P}param01=" + edt_BASE_DD.getValue() + "&{P}param02=" + edt_BASE_DD.getValue() + "&{P}param03=" + edt_BASE_DD.getValue() + "&{P}param04=" + edt_BASE_DD.getValue();
    } else if (rdo_MARKET_TP_CD.getValue() === '2') {
        url += "&queryId=lds.stf.lstsrch.select.mainstat.admisu.kosdaq.condition" + "&{P}param01=" + edt_BASE_DD.getValue();
    }
    const sbmOptions = {
        id : "sbm_dts_List_2",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync3
 * @description list Sync3 처리
 * @returns {Promise<void>}
