 */
scwin.listSync3 = async function() {
    url += "?SCREN_ID=" + "ULDSTF20001.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LISTSRH_MAINSTAT_NEWLISTING_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.mainstat.newlisting.condition" + "&{P}param01=" + edt_BASE_YYYY.getValue() + "&{P}param02=" + rdo_MARKET_TP_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_List_3",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_3=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkSearch
 * @description check Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSearch = async function() {
    if (edt_BASE_DD.getValue().length !== 8) {
        await $c.win.alert("기준일을 선택하세요");
        edt_BASE_DD.focus();
        return false;
    }
    if (edt_BASE_DD.getValue() > $c.ut.cGetToday("yyyymmdd")) {
        await $c.win.alert("기준일이 현재일보다 큽니다.");
        edt_BASE_DD.focus();
        return false;
    }
    return true;
};
